Analyzing the demo: the seed object (8,1,1 vertical) gets stamped centered on every scattered marker (3). Marker = center of the pattern's bounding box. In the test, the seed is the 3×3 blob (rows 11–13, cols 6–8) and the scattered 1s are markers; stamping centered on each keeps everything in bounds.

```python
from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != bg]
    # connected components (8-conn)
    cellset = {(r, c) for r, c, v in cells}
    seen, comps = set(), []
    for cell in cellset:
        if cell in seen:
            continue
        stack, comp = [cell], []
        seen.add(cell)
        while stack:
            r, c = stack.pop()
            comp.append((r, c))
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    n = (r + dr, c + dc)
                    if n in cellset and n not in seen:
                        seen.add(n)
                        stack.append(n)
        comps.append(comp)
    seed = max(comps, key=len)
    seed_cells = {(r, c): grid[r][c] for r, c in seed}
    marker_cells = [(r, c, grid[r][c]) for r, c, v in cells if (r, c) not in seed_cells]
    rs = [r for r, c in seed]; cs = [c for r, c in seed]
    r0, c0 = min(rs), min(cs)
    ph, pw = max(rs) - r0 + 1, max(cs) - c0 + 1
    ch, cw = ph // 2, pw // 2
    pattern = {(r - r0, c - c0): v for (r, c), v in seed_cells.items()}
    out = [[bg] * w for _ in range(h)]
    for r, c, v in marker_cells:
        for (dr, dc), pv in pattern.items():
            if pv == bg:
                continue
            rr, cc = r - ch + dr, c - cw + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = pv
    for (r, c), v in seed_cells.items():
        out[r][c] = v
    return out
